export const SITE_TEMPLATE = {"id":"static-site","version":"1.0.0"};
export const SITE_TEMPLATE_FILES = Object.freeze({
  "scripts/build.mjs": "import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { createRenderer, validateSite } from \"./render.mjs\";\n\n// Generated by Atlas Genesis (static-site template). Renders every page in\n// site.json to dist/, with shared navigation, SEO basics and a sitemap.\n\nconst root = process.cwd();\nconst site = JSON.parse(readFileSync(join(root, \"site.json\"), \"utf8\"));\nconst dist = join(root, \"dist\");\n\nconst problems = validateSite(site);\nif (problems.length) { console.error(`Build failed:\\n- ${problems.join(\"\\n- \")}`); process.exit(1); }\nconst { origin, fileFor, render, sitemap, robots } = createRenderer(site);\n\nrmSync(dist, { recursive: true, force: true });\nmkdirSync(dist, { recursive: true });\nfor (const page of site.pages) writeFileSync(join(dist, fileFor(page)), render(page));\ncopyFileSync(join(root, \"src\", \"styles.css\"), join(dist, \"styles.css\"));\ncopyFileSync(join(root, \"src\", \"contact.js\"), join(dist, \"contact.js\"));\nwriteFileSync(join(dist, \"sitemap.xml\"), sitemap());\nwriteFileSync(join(dist, \"robots.txt\"), robots());\nif (!origin) console.warn(\"Note: set \\\"url\\\" in site.json to your live address so canonical links and the sitemap are absolute.\");\nconsole.log(`✓ Built ${site.pages.length} pages for ${site.name} into dist/`);\n",
  "scripts/check.mjs": "import { spawnSync } from \"node:child_process\";\nimport { readFileSync, readdirSync, statSync } from \"node:fs\";\nimport { join, relative } from \"node:path\";\n\n// Generated by Atlas Genesis. Syntax-checks every JavaScript file, and fails on\n// leftovers that should never ship: debugger statements and placeholder Latin.\n\nconst root = process.cwd();\nconst skip = new Set([\"node_modules\", \"dist\", \"data\", \".git\", \".atlas\"]);\nconst files = [];\n(function walk(dir) {\n  for (const name of readdirSync(dir)) {\n    if (skip.has(name)) continue;\n    const path = join(dir, name);\n    if (statSync(path).isDirectory()) walk(path);\n    else if (/\\.(m?js|html|css)$/u.test(name)) files.push(path);\n  }\n})(root);\n\nlet failures = 0;\nfor (const file of files) {\n  if (/\\.m?js$/u.test(file)) {\n    const result = spawnSync(process.execPath, [\"--check\", file], { encoding: \"utf8\" });\n    if (result.status !== 0) { failures += 1; console.error(`✗ ${relative(root, file)}\\n${result.stderr}`); }\n  }\n  const text = readFileSync(file, \"utf8\");\n  if (/\\bdebugger\\s*;/u.test(text)) { failures += 1; console.error(`✗ ${relative(root, file)}: remove the debugger statement`); }\n  if (/lorem\\s+ipsum/iu.test(text)) { failures += 1; console.error(`✗ ${relative(root, file)}: placeholder text`); }\n}\nif (failures) { console.error(`${failures} problem(s) in ${files.length} files.`); process.exit(1); }\nconsole.log(`✓ ${files.length} files checked.`);\n",
  "scripts/render.mjs": "// Generated by Atlas Genesis (static-site template). Pure: turns site.json into\n// pages, a sitemap and robots.txt with no file system or process access, so the\n// same code builds dist/ here and renders the live preview on the hosted app.\n\n/** Problems that stop a build, as plain sentences. Empty when site.json is usable. */\nexport function validateSite(site) {\n  const problems = [];\n  if (!site?.name) problems.push(\"site.json has no name\");\n  if (!site?.pages?.some((page) => page.id === \"home\")) problems.push(\"site.json needs a home page\");\n  for (const page of site?.pages ?? []) {\n    if (!page.title || !page.headline) problems.push(`page ${page.id} needs a title and a headline`);\n    if (!page.description || page.description.length > 160) problems.push(`page ${page.id} needs a description of at most 160 characters`);\n  }\n  return problems;\n}\n\n/**\n * @param {object} site  parsed site.json\n * @param {{ base?: string, year?: number }} [options]  base prefixes every internal link (a preview lives under a path)\n */\nexport function createRenderer(site, { base = \"\", year = new Date().getFullYear() } = {}) {\n  const escape = (value) => String(value ?? \"\").replace(/[&<>\"']/gu, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\n  const fileFor = (page) => (page.id === \"home\" ? \"index.html\" : `${page.id}.html`);\n  const homeHref = base || \"/\";\n  const hrefFor = (page) => (page.id === \"home\" ? homeHref : `${base}/${page.id}.html`);\n  // Canonical URLs and sitemap entries must be absolute. Set \"url\" in site.json to the live address; until then\n  // they stay site-relative and the build says so.\n  const origin = String(site.url ?? \"\").replace(/\\/+$/u, \"\");\n  const absolute = (page) => `${origin}${hrefFor(page)}`;\n  // Structured data states only what site.json states: no address, phone, rating or hours are ever made up.\n  const localBusiness = () => JSON.stringify({\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"LocalBusiness\",\n    name: site.name,\n    ...(origin ? { url: origin } : {}),\n    ...(site.contact.phone ? { telephone: site.contact.phone } : {}),\n    ...(site.contact.email ? { email: site.contact.email } : {}),\n    ...(site.location?.city ? { areaServed: { \"@type\": \"City\", name: [site.location.city, site.location.region].filter(Boolean).join(\", \") } } : {}),\n  }).replace(/</gu, \"\\\\u003c\");\n\n\n  function section(block) {\n    if (block.type === \"cards\") {\n      return `<section class=\"band\"><h2>${escape(block.title)}</h2><div class=\"cards\">${block.items.map((item) => `<article class=\"card\"><h3>${escape(item.title)}</h3><p>${escape(item.text)}</p></article>`).join(\"\")}</div></section>`;\n    }\n    if (block.type === \"steps\") {\n      return `<section class=\"band\"><h2>${escape(block.title)}</h2><ol class=\"steps\">${block.items.map((item) => `<li><strong>${escape(item.title)}</strong> ${escape(item.text)}</li>`).join(\"\")}</ol></section>`;\n    }\n    if (block.type === \"gallery\") {\n      return `<section class=\"band\"><h2>${escape(block.title)}</h2><div class=\"gallery\">${block.items.map((item) => `<figure class=\"tile\"><div class=\"swatch\" aria-hidden=\"true\"></div><figcaption>${escape(item)}</figcaption></figure>`).join(\"\")}</div><p class=\"note\">${escape(block.note ?? \"\")}</p></section>`;\n    }\n    if (block.type === \"contact\") {\n      return `<section class=\"band contact\"><div><h2>${escape(block.title)}</h2><p>${escape(block.text)}</p><ul class=\"details\">${site.contact.phone ? `<li>Phone: <a href=\"tel:${escape(site.contact.phone)}\">${escape(site.contact.phone)}</a></li>` : \"\"}${site.contact.email ? `<li>Email: <a href=\"mailto:${escape(site.contact.email)}\">${escape(site.contact.email)}</a></li>` : \"\"}${site.contact.area ? `<li>Service area: ${escape(site.contact.area)}</li>` : \"\"}</ul></div>\n<form id=\"enquiry\" class=\"card form\" novalidate>\n  <div class=\"field\"><label for=\"name\">Name *</label><input id=\"name\" name=\"name\" autocomplete=\"name\" required></div>\n  <div class=\"field\"><label for=\"email\">Email *</label><input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required></div>\n  <div class=\"field\"><label for=\"phone\">Phone</label><input id=\"phone\" name=\"phone\" type=\"tel\" autocomplete=\"tel\"></div>\n  <div class=\"field\"><label for=\"message\">How can we help? *</label><textarea id=\"message\" name=\"message\" rows=\"4\" required></textarea></div>\n  <p class=\"form-error\" id=\"enquiry-error\" role=\"alert\" hidden></p>\n  <button type=\"submit\">Send enquiry</button>\n</form>\n<div class=\"card success\" id=\"enquiry-done\" role=\"status\" hidden><h3>Thank you!</h3><p>We received your message and will reply soon.</p></div></section>`;\n    }\n    return `<section class=\"band\"><h2>${escape(block.title)}</h2>${(block.paragraphs ?? []).map((p) => `<p>${escape(p)}</p>`).join(\"\")}</section>`;\n  }\n\n  function render(page) {\n    const nav = site.pages.map((item) => `<a href=\"${hrefFor(item)}\"${item.id === page.id ? ' aria-current=\"page\"' : \"\"}>${escape(item.title)}</a>`).join(\"\");\n    const hasForm = page.sections.some((block) => block.type === \"contact\");\n    return `<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>${escape(page.id === \"home\" ? `${site.name} · ${site.tagline}` : `${page.title} · ${site.name}`)}</title>\n<meta name=\"description\" content=\"${escape(page.description)}\">\n<link rel=\"canonical\" href=\"${origin ? absolute(page) : hrefFor(page)}\">\n<meta property=\"og:title\" content=\"${escape(page.title)} · ${escape(site.name)}\">\n<meta property=\"og:description\" content=\"${escape(page.description)}\">\n<meta property=\"og:type\" content=\"website\">${page.id === \"home\" ? `\\n<script type=\"application/ld+json\">${localBusiness()}</script>` : \"\"}\n<link rel=\"stylesheet\" href=\"${base}/styles.css\">${hasForm ? `\\n<script type=\"module\" src=\"${base}/contact.js\"></script>` : \"\"}\n</head>\n<body>\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<header class=\"topbar\"><a class=\"brand\" href=\"${homeHref}\">${escape(site.name)}</a><nav aria-label=\"Main\">${nav}</nav></header>\n<main id=\"main\">\n<section class=\"hero\"><h1>${escape(page.headline)}</h1><p class=\"lead\">${escape(page.intro)}</p>${page.id !== \"contact\" ? `<a class=\"button\" href=\"${base}/contact.html\">${escape(site.cta)}</a>` : \"\"}</section>\n${page.sections.map(section).join(\"\\n\")}\n</main>\n<footer class=\"footer\"><p>© ${year} ${escape(site.name)}${site.contact.area ? ` · ${escape(site.contact.area)}` : \"\"}</p></footer>\n</body>\n</html>\n`;\n  }\n\n\n  const sitemap = () => `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\\n${site.pages.map((page) => `  <url><loc>${escape(origin ? absolute(page) : hrefFor(page))}</loc></url>`).join(\"\\n\")}\\n</urlset>\\n`;\n  const robots = () => `User-agent: *\\nAllow: /\\nSitemap: ${origin}/sitemap.xml\\n`;\n  return { origin, fileFor, hrefFor, render, sitemap, robots };\n}\n",
  "server.mjs": "import { appendFileSync, mkdirSync } from \"node:fs\";\nimport { createServer } from \"node:http\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\nimport { readJson, sendJson, serveStatic } from \"./src/http.mjs\";\n\n// Generated by Atlas Genesis (static-site template). Serves the built pages in\n// dist/ and records enquiries from the contact form in data/enquiries.jsonl.\n\nconst here = dirname(fileURLToPath(import.meta.url));\nconst EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/u;\n\nexport function validateEnquiry(input) {\n  const errors = {};\n  const clean = {};\n  for (const key of [\"name\", \"email\", \"phone\", \"message\"]) clean[key] = typeof input[key] === \"string\" ? input[key].trim().slice(0, 2000) : \"\";\n  if (!clean.name) errors.name = \"Please tell us your name.\";\n  if (!EMAIL.test(clean.email)) errors.email = \"Please enter a valid email address.\";\n  if (!clean.message) errors.message = \"Please tell us how we can help.\";\n  return { clean, errors };\n}\n\nexport function createApp({ distDir = join(here, \"dist\"), enquiriesFile = join(here, \"data\", \"enquiries.jsonl\") } = {}) {\n  return createServer(async (request, response) => {\n    const url = new URL(request.url ?? \"/\", \"http://localhost\");\n    try {\n      if (url.pathname === \"/api/health\") return sendJson(response, 200, { ok: true });\n      if (url.pathname === \"/api/enquiries\") {\n        if (request.method !== \"POST\") return sendJson(response, 405, { error: \"Method not allowed.\" });\n        const { clean, errors } = validateEnquiry(await readJson(request));\n        if (Object.keys(errors).length) return sendJson(response, 400, { error: Object.values(errors)[0], errors });\n        if (enquiriesFile) {\n          mkdirSync(dirname(enquiriesFile), { recursive: true });\n          appendFileSync(enquiriesFile, `${JSON.stringify({ ...clean, receivedAt: new Date().toISOString() })}\\n`);\n        }\n        return sendJson(response, 201, { received: true });\n      }\n      if (request.method !== \"GET\" && request.method !== \"HEAD\") return sendJson(response, 405, { error: \"Method not allowed.\" });\n      return await serveStatic(response, distDir, url.pathname);\n    } catch (error) {\n      return sendJson(response, error.status ?? 500, { error: error.status ? error.message : \"Something went wrong.\" });\n    }\n  });\n}\n\nif (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {\n  const port = Number(process.env.PORT || 3000);\n  const host = process.env.HOST || \"127.0.0.1\";\n  createApp().listen(port, host, () => console.log(`Site running at http://${host}:${port}`));\n}\n",
  "src/contact.js": "// Generated by Atlas Genesis (static-site template). Sends the enquiry form.\n\nconst form = document.getElementById(\"enquiry\");\nconst error = document.getElementById(\"enquiry-error\");\nconst done = document.getElementById(\"enquiry-done\");\n\nform?.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const button = form.querySelector(\"button[type=submit]\");\n  const data = Object.fromEntries(new FormData(form).entries());\n  error.hidden = true;\n  // Check in the browser first; the server checks again.\n  const problem = !String(data.name ?? \"\").trim() ? \"Please tell us your name.\"\n    : !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/u.test(String(data.email ?? \"\").trim()) ? \"Please enter a valid email address.\"\n      : !String(data.message ?? \"\").trim() ? \"Please tell us how we can help.\" : null;\n  if (problem) {\n    error.textContent = problem;\n    error.hidden = false;\n    return;\n  }\n  button.disabled = true;\n  try {\n    const response = await fetch(\"/api/enquiries\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(data) });\n    const body = await response.json().catch(() => ({}));\n    if (!response.ok) throw new Error(body.error ?? \"The message could not be sent.\");\n    form.hidden = true;\n    done.hidden = false;\n  } catch (failure) {\n    error.textContent = failure.message;\n    error.hidden = false;\n  } finally {\n    button.disabled = false;\n  }\n});\n",
  "src/http.mjs": "import { readFile } from \"node:fs/promises\";\nimport { extname, join, normalize, sep } from \"node:path\";\n\n// Generated by Atlas Genesis. Small HTTP helpers with safe defaults.\n\nexport const MAX_BODY_BYTES = 64 * 1024;\n\nconst TYPES = {\n  \".html\": \"text/html; charset=utf-8\",\n  \".css\": \"text/css; charset=utf-8\",\n  \".js\": \"text/javascript; charset=utf-8\",\n  \".mjs\": \"text/javascript; charset=utf-8\",\n  \".json\": \"application/json; charset=utf-8\",\n  \".svg\": \"image/svg+xml\",\n  \".png\": \"image/png\",\n  \".ico\": \"image/x-icon\",\n  \".xml\": \"application/xml; charset=utf-8\",\n  \".txt\": \"text/plain; charset=utf-8\",\n};\n\n/** Security headers on every response: no inline scripts, no framing, no sniffing. */\nexport function secure(response) {\n  response.setHeader(\"content-security-policy\", \"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\");\n  response.setHeader(\"x-content-type-options\", \"nosniff\");\n  response.setHeader(\"referrer-policy\", \"no-referrer\");\n  response.setHeader(\"x-frame-options\", \"DENY\");\n}\n\nexport function sendJson(response, status, value) {\n  secure(response);\n  response.writeHead(status, { \"content-type\": \"application/json; charset=utf-8\", \"cache-control\": \"no-store\" });\n  response.end(JSON.stringify(value));\n}\n\nexport async function readJson(request) {\n  const chunks = [];\n  let size = 0;\n  for await (const chunk of request) {\n    size += chunk.length;\n    if (size > MAX_BODY_BYTES) throw Object.assign(new Error(\"The request is too large.\"), { status: 413 });\n    chunks.push(chunk);\n  }\n  if (!chunks.length) return {};\n  try {\n    const value = JSON.parse(Buffer.concat(chunks).toString(\"utf8\"));\n    if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Error(\"not an object\");\n    return value;\n  } catch {\n    throw Object.assign(new Error(\"The request body must be a JSON object.\"), { status: 400 });\n  }\n}\n\n/** Serves a file from `root` only; anything outside it, or missing, falls back to `fallback` (or 404). */\nexport async function serveStatic(response, root, pathname, { fallback = null } = {}) {\n  const decoded = (() => { try { return decodeURIComponent(pathname); } catch { return \"/\"; } })();\n  const relative = normalize(decoded).replace(/^([/\\\\])+/u, \"\");\n  const target = join(root, relative || \"index.html\");\n  const inside = target === root || target.startsWith(root.endsWith(sep) ? root : root + sep);\n  const candidates = inside ? [target, join(target, \"index.html\"), `${target}.html`] : [];\n  if (fallback) candidates.push(join(root, fallback));\n  for (const file of candidates) {\n    try {\n      const body = await readFile(file);\n      secure(response);\n      response.writeHead(200, { \"content-type\": TYPES[extname(file)] ?? \"application/octet-stream\", \"cache-control\": \"no-cache\" });\n      response.end(body);\n      return true;\n    } catch { /* next candidate */ }\n  }\n  sendJson(response, 404, { error: \"Not found.\" });\n  return false;\n}\n",
  "src/styles.css": "/* Generated by Atlas Genesis (static-site template). */\n:root {\n  --accent: #b45309;\n  --bg: #fbfaf8;\n  --surface: #ffffff;\n  --text: #1c1917;\n  --muted: #57534e;\n  --line: #e7e5e4;\n  --danger: #b42318;\n  --radius: 14px;\n  font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  color-scheme: light;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--text); line-height: 1.6; }\na { color: var(--accent); }\n.skip { position: absolute; left: -999px; }\n.skip:focus { left: 12px; top: 12px; background: var(--surface); padding: 8px 12px; border-radius: 8px; }\n.topbar { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 24px; padding: 16px 24px; background: var(--surface); border-bottom: 1px solid var(--line); }\n.brand { font-weight: 800; font-size: 1.15rem; color: var(--text); text-decoration: none; margin-right: auto; }\nnav { display: flex; flex-wrap: wrap; gap: 4px; }\nnav a { padding: 6px 12px; border-radius: 8px; color: var(--muted); text-decoration: none; font-weight: 500; }\nnav a:hover, nav a[aria-current=\"page\"] { color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, transparent); }\nmain { max-width: 1080px; margin: 0 auto; padding: 0 24px 48px; }\n.hero { padding: 64px 0 40px; max-width: 720px; }\n.hero h1 { font-size: clamp(2rem, 5vw, 3rem); line-height: 1.15; margin: 0 0 16px; letter-spacing: -0.02em; }\n.lead { font-size: 1.15rem; color: var(--muted); margin: 0 0 24px; }\n.button, button { display: inline-block; font: inherit; font-weight: 700; background: var(--accent); color: #fff; border: 0; border-radius: 10px; padding: 12px 20px; text-decoration: none; cursor: pointer; }\nbutton:disabled { opacity: 0.6; }\n.band { padding: 32px 0; border-top: 1px solid var(--line); }\n.band h2 { font-size: 1.5rem; margin: 0 0 20px; }\n.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; }\n.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px; }\n.card h3 { margin: 0 0 8px; font-size: 1.1rem; }\n.card p { margin: 0; color: var(--muted); }\n.steps { padding-left: 20px; }\n.steps li { margin-bottom: 10px; }\n.gallery { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }\n.tile { margin: 0; }\n.swatch { aspect-ratio: 4 / 3; border-radius: 10px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 35%, #fff), color-mix(in srgb, var(--accent) 70%, #000)); }\n.tile figcaption { font-size: 0.9rem; color: var(--muted); margin-top: 6px; }\n.note { color: var(--muted); font-size: 0.9rem; }\n.contact { display: grid; grid-template-columns: 1fr 1.2fr; gap: 32px; align-items: start; }\n.details { list-style: none; padding: 0; }\n.form { display: grid; gap: 14px; }\n.field label { display: block; font-weight: 600; margin-bottom: 4px; }\ninput, textarea { width: 100%; font: inherit; border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; background: #fff; color: inherit; }\ninput:focus-visible, textarea:focus-visible, a:focus-visible, button:focus-visible { outline: 3px solid color-mix(in srgb, var(--accent) 45%, transparent); outline-offset: 2px; }\n.form-error { color: var(--danger); margin: 0; }\n.footer { border-top: 1px solid var(--line); padding: 24px; text-align: center; color: var(--muted); }\n@media (max-width: 720px) {\n  .topbar { padding: 12px 16px; }\n  main { padding: 0 16px 32px; }\n  .hero { padding: 40px 0 24px; }\n  .contact { grid-template-columns: 1fr; }\n}\n",
  "tests/site.test.mjs": "import assert from \"node:assert/strict\";\nimport { spawnSync } from \"node:child_process\";\nimport { existsSync, mkdtempSync, readFileSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport test from \"node:test\";\nimport { createApp, validateEnquiry } from \"../server.mjs\";\n\n// Generated by Atlas Genesis (static-site template).\n\nconst root = process.cwd();\nconst site = JSON.parse(readFileSync(join(root, \"site.json\"), \"utf8\"));\n\ntest(\"the build renders every page with a title, description, heading and navigation\", () => {\n  const result = spawnSync(process.execPath, [\"scripts/build.mjs\"], { cwd: root, encoding: \"utf8\" });\n  assert.equal(result.status, 0, result.stderr);\n  for (const page of site.pages) {\n    const file = join(root, \"dist\", page.id === \"home\" ? \"index.html\" : `${page.id}.html`);\n    assert.ok(existsSync(file), `${page.id} was built`);\n    const html = readFileSync(file, \"utf8\");\n    assert.match(html, /<title>[^<]+<\\/title>/u);\n    assert.match(html, /<meta name=\"description\" content=\"[^\"]+\">/u);\n    assert.ok(html.includes(`<h1>`), `${page.id} has a heading`);\n    for (const other of site.pages) assert.ok(html.includes(other.id === \"home\" ? 'href=\"/\"' : `href=\"/${other.id}.html\"`), `${page.id} links to ${other.id}`);\n  }\n  const sitemap = readFileSync(join(root, \"dist\", \"sitemap.xml\"), \"utf8\");\n  assert.equal((sitemap.match(/<url>/gu) ?? []).length, site.pages.length);\n});\n\ntest(\"the enquiry form validates and records submissions\", async () => {\n  assert.deepEqual(Object.keys(validateEnquiry({}).errors).sort(), [\"email\", \"message\", \"name\"]);\n  const directory = mkdtempSync(join(tmpdir(), \"site-\"));\n  const server = createApp({ distDir: join(root, \"dist\"), enquiriesFile: join(directory, \"enquiries.jsonl\") });\n  await new Promise((resolve) => server.listen(0, \"127.0.0.1\", resolve));\n  const base = `http://127.0.0.1:${server.address().port}`;\n  try {\n    const bad = await fetch(`${base}/api/enquiries`, { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ name: \"Sam\" }) });\n    assert.equal(bad.status, 400);\n    const good = await fetch(`${base}/api/enquiries`, { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ name: \"Sam\", email: \"sam@example.com\", message: \"A quote, please\" }) });\n    assert.equal(good.status, 201);\n    assert.match(readFileSync(join(directory, \"enquiries.jsonl\"), \"utf8\"), /A quote, please/u);\n    const home = await fetch(`${base}/`);\n    assert.equal(home.status, 200);\n    assert.match(home.headers.get(\"content-security-policy\"), /script-src 'self'/u);\n  } finally {\n    await new Promise((resolve) => server.close(resolve));\n    rmSync(directory, { recursive: true, force: true });\n  }\n});\n",
});
